const datosEntrada = $('Start').first().json || {};
const diasPeriodo = parseInt(datosEntrada.periodo) || 14; 
const CAPACIDAD_HOTEL = 75;
const HORIZONTES = Array.from({ length: diasPeriodo }, (_, i) => i + 1);

const PAIS_DUMMIES = ["Pais_EEUU","Pais_España","Pais_Francia","Pais_Italia","Pais_Otros","Pais_Portugal","Pais_Reino Unido"];
const PAIS_MAP = { "EEUU":"Pais_EEUU", "España":"Pais_España", "Francia":"Pais_Francia", "Italia":"Pais_Italia", "Portugal":"Pais_Portugal", "Reino Unido":"Pais_Reino Unido" };

const CANAL_DUMMIES = ["Canal_Booking","Canal_Expedia","Canal_Otros","Canal_Teléfono","Canal_Walk-in","Canal_Web"];
const CANAL_MAP = { "Booking":"Canal_Booking", "Expedia":"Canal_Expedia", "Teléfono":"Canal_Teléfono", "Walk-in":"Canal_Walk-in", "Web":"Canal_Web" };
const CANAL_REFERENCIA = "Agencia";

const TIPO_DUMMIES = ["Tipo_Individual","Tipo_Otros","Tipo_Suite"];
const TIPO_MAP = { "Individual":"Tipo_Individual", "Suite":"Tipo_Suite" };
const TIPO_REFERENCIA = "Doble";

const ESTADOS_VALIDOS = ["Confirmada", "No Show"];

function parseDate(str) {
  const d = new Date(str);
  return new Date(Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate()));
}
function addDays(date, n) { const d = new Date(date); d.setUTCDate(d.getUTCDate() + n); return d; }
function addYears(date, n) { return new Date(Date.UTC(date.getUTCFullYear() + n, date.getUTCMonth(), date.getUTCDate())); }
function toISODate(date) { return date.toISOString().slice(0, 10); }
function pyDayOfWeek(date) { return (date.getUTCDay() + 6) % 7; }
function isoWeek(date) {
  const d = new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate()));
  d.setUTCDate(d.getUTCDate() + 4 - (d.getUTCDay() || 7));
  const yearStart = new Date(Date.UTC(d.getUTCFullYear(), 0, 1));
  return Math.ceil((((d - yearStart) / 86400000) + 1) / 7);
}
function mean(arr) { 
  const valids = arr.filter(v => typeof v === 'number' && !isNaN(v));
  return valids.length ? valids.reduce((a, b) => a + b, 0) / valids.length : 0; 
}
function moda(arr) {
  if (!arr.length) return null;
  const counts = {};
  arr.forEach(v => { if (v) counts[v] = (counts[v] || 0) + 1; });
  const sorted = Object.entries(counts).sort((a, b) => b[1] - a[1]);
  return sorted.length ? sorted[0][0] : null;
}

// Función genérica para desglose por atributo (canal, pais, tipo, etc.)
function distribucionPorCampo(vigentes, campo) {
  const grupos = {};
  vigentes.forEach(r => {
    const valor = r[campo] || 'Otros';
    if (!grupos[valor]) grupos[valor] = [];
    grupos[valor].push(r);
  });
  const resultado = {};
  Object.entries(grupos).forEach(([valor, res]) => {
    resultado[valor] = {
      habitaciones_vendidas: res.length,
      adr_medio: Number(mean(res.map(r => r.adr)).toFixed(2))
    };
  });
  return resultado;
}

function asignarDummies(valor, mapa, dummiesArray, referencia, colOtros) {
  const dummies = {};
  dummiesArray.forEach(col => dummies[col] = 0);
  if (!valor || valor === referencia) return dummies;
  if (mapa[valor]) { dummies[mapa[valor]] = 1; return dummies; }
  dummies[colOtros] = 1;
  return dummies;
}

const reservas = $('Extract from File').all()
  .map((item, index) => {
    const f = item.json;
    return {
      id: index,
      checkIn: parseDate(f.CheckIn),
      fechaReserva: parseDate(f.FechaReserva),
      adr: Number(f.ADR) || 0,
      pais: f.Pais,
      canal: f.Canal,
      tipo: f.Tipo,
      estado: f.Estado,
      checkOut: f.CheckOut ? parseDate(f.CheckOut) : null
    };
  })
  .filter(r => ESTADOS_VALIDOS.includes(r.estado));

const hoy = new Date(Date.UTC(new Date().getUTCFullYear(), new Date().getUTCMonth(), new Date().getUTCDate()));

const contextoExternoSerie = datosEntrada.contextoExternoSerie || [];
const externoPorFecha = {};
contextoExternoSerie.forEach(d => { externoPorFecha[d.fecha] = d; });

const historicoDiarioPorFecha = {};
items.forEach(item => {
  const h = item.json;
  if (h.fecha) historicoDiarioPorFecha[h.fecha] = h;
});

const resultados = HORIZONTES.map(dias_vista => {
  const fechaObjetivo = addDays(hoy, dias_vista);

  const vigentes = reservas.filter(r =>
    r.checkIn <= fechaObjetivo && 
    (r.checkOut ? r.checkOut > fechaObjetivo : toISODate(r.checkIn) === toISODate(fechaObjetivo)) && 
    r.fechaReserva <= hoy
  );

  const habitacionesVendidasSet = new Set(vigentes.map(r => r.id));
  const habitaciones_vendidas = habitacionesVendidasSet.size;

  const ocupacion_actual = (habitaciones_vendidas / CAPACIDAD_HOTEL) * 100;
  const adr_actual = mean(vigentes.map(r => r.adr));
  const leadTimes = vigentes.map(r => Math.max(0, (r.checkIn - r.fechaReserva) / 86400000));
  const lead_time = leadTimes.length ? mean(leadTimes) : dias_vista;

  const reservasFecha = reservas.filter(r => 
      r.checkIn <= fechaObjetivo && 
      (r.checkOut ? r.checkOut > fechaObjetivo : toISODate(r.checkIn) === toISODate(fechaObjetivo))
  );

  const pickup_7 = reservasFecha.filter(r => r.fechaReserva > addDays(hoy, -7) && r.fechaReserva <= hoy).length;
  const pickup_14 = reservasFecha.filter(r => r.fechaReserva > addDays(hoy, -14) && r.fechaReserva <= hoy).length;

  const nochesVigentes = vigentes
    .filter(r => r.checkOut)
    .map(r => Math.max(1, (r.checkOut - r.checkIn) / 86400000));
  const estancia_media_noches = nochesVigentes.length ? Number(mean(nochesVigentes).toFixed(1)) : null;

  const ritmo_pickup = pickup_14 > 0 ? Number((pickup_7 / (pickup_14 / 2)).toFixed(2)) : null;

  const fechaAnioAnterior = toISODate(addYears(fechaObjetivo, -1));
  const histAnioAnterior = historicoDiarioPorFecha[fechaAnioAnterior];
  const sinDatoHistoricoYoy = !histAnioAnterior;
  const ocupacion_anio_anterior = histAnioAnterior ? histAnioAnterior.ocupacion_final : null;
  const adr_anio_anterior = histAnioAnterior ? histAnioAnterior.adr_final : null;

  const paisModa = moda(vigentes.map(r => r.pais));
  const paisDummies = asignarDummies(paisModa, PAIS_MAP, PAIS_DUMMIES, null, "Pais_Otros");

  const canalModa = moda(vigentes.map(r => r.canal));
  const canalDummies = asignarDummies(canalModa, CANAL_MAP, CANAL_DUMMIES, CANAL_REFERENCIA, "Canal_Otros");

  const tipoModa = moda(vigentes.map(r => r.tipo));
  const tipoDummies = asignarDummies(tipoModa, TIPO_MAP, TIPO_DUMMIES, TIPO_REFERENCIA, "Tipo_Otros");

  const Mes = fechaObjetivo.getUTCMonth() + 1;
  const DiaSemana = pyDayOfWeek(fechaObjetivo);
  const DiaMes = fechaObjetivo.getUTCDate();
  const Año = fechaObjetivo.getUTCFullYear();
  const Semana = isoWeek(fechaObjetivo);
  const FinSemana = DiaSemana >= 5 ? 1 : 0;

  const diaExterno = externoPorFecha[toISODate(fechaObjetivo)] || {};
  const Festivo = diaExterno.es_festivo ? 1 : 0; 

  const Es_Verano = [6, 7, 8].includes(Mes) ? 1 : 0;
  const Es_Invierno = [12, 1, 2].includes(Mes) ? 1 : 0;
  const Es_Puente = 0;
  const FinMes = DiaMes >= 25 ? 1 : 0;
  const InicioMes = DiaMes <= 5 ? 1 : 0;
  const Mes_sin = Math.sin(2 * Math.PI * Mes / 12);
  const Mes_cos = Math.cos(2 * Math.PI * Mes / 12);
  const DiaSemana_sin = Math.sin(2 * Math.PI * DiaSemana / 7);
  const DiaSemana_cos = Math.cos(2 * Math.PI * DiaSemana / 7);

  const ocupacion_anio_anterior_modelo = sinDatoHistoricoYoy ? ocupacion_actual : ocupacion_anio_anterior;
  const adr_anio_anterior_modelo = sinDatoHistoricoYoy ? adr_actual : adr_anio_anterior;

  const inputModelo = {
    Fecha: toISODate(fechaObjetivo), 
    dias_vista, habitaciones_vendidas, ocupacion_actual, adr_actual, lead_time,
    ...canalDummies,
    ...tipoDummies,
    ...paisDummies,
    pickup_7, pickup_14,
    ocupacion_anio_anterior: ocupacion_anio_anterior_modelo,
    adr_anio_anterior: adr_anio_anterior_modelo,
    Mes, Semana, DiaMes, DiaSemana, FinSemana, Año,
    Festivo, Es_Verano, Es_Invierno, Es_Puente, FinMes, InicioMes,
    Mes_sin, Mes_cos, DiaSemana_sin, DiaSemana_cos
  };

  return {
    json: {
      contextoNegocio: {
        fecha: toISODate(fechaObjetivo),
        horizonte_dias: dias_vista,
        ocupacion_actual_pct: Math.round(ocupacion_actual * 100) / 100,
        adr_actual_eur: Math.round(adr_actual * 100) / 100,
        ocupacion_mismo_periodo_anio_anterior: ocupacion_anio_anterior != null ? Math.round(ocupacion_anio_anterior * 100) / 100 : null,
        adr_mismo_periodo_anio_anterior: adr_anio_anterior != null ? Math.round(adr_anio_anterior * 100) / 100 : null,
        sin_dato_historico_yoy: sinDatoHistoricoYoy,
        pickup_ultimos_7_dias: pickup_7,
        pickup_ultimos_14_dias: pickup_14,
        estancia_media_noches,
        ritmo_pickup, CAPACIDAD_HOTEL,
        canal_moda: canalModa,
        tipo_moda: tipoModa,
        pais_moda: paisModa,
        canal_detalle: distribucionPorCampo(vigentes, 'canal'),
        pais_detalle: distribucionPorCampo(vigentes, 'pais'),
        tipo_detalle: distribucionPorCampo(vigentes, 'tipo')
      },
      inputModelo
    }
  };
});

return resultados;

const variablesModelo = [
  "Fecha", 
  "dias_vista", "ocupacion_actual", "adr_actual", "lead_time", 
  "Canal_Booking", "Canal_Expedia", "Canal_Otros", "Canal_Teléfono", "Canal_Walk-in", "Canal_Web",
  "Tipo_Individual", "Tipo_Otros", "Tipo_Suite",
  "Pais_EEUU", "Pais_España", "Pais_Francia", "Pais_Italia", "Pais_Otros", "Pais_Portugal", "Pais_Reino Unido", 
  "pickup_7", "pickup_14", "ocupacion_anio_anterior", "adr_anio_anterior", "Semana", 
  "DiaMes", "FinSemana", "Festivo", "Es_Verano", "Es_Invierno", 
  "FinMes", "InicioMes", "Mes_sin", "Mes_cos", "DiaSemana_sin", "DiaSemana_cos"
];

// Rescatamos los datos originales que entraron por el nodo Start
const datosEntrada = $('Start').first().json || {};

const inputModeloArray = items.map(function(item) {
  const modeloEntrada = item.json.inputModelo || {};
  const inputModeloValidado = {};

  variablesModelo.forEach(function(v) {
    if (modeloEntrada[v] === undefined) {
      throw new Error("Falta la variable \"" + v + "\" en el día dias_vista=" + (modeloEntrada.dias_vista || '?') + ".");
    }
    inputModeloValidado[v] = modeloEntrada[v];
  });

  return inputModeloValidado;
});

const contextoNegocioSerie = items.map(function(item) {
  return item.json.contextoNegocio;
});

return [{
  json: {
    inputModelo: inputModeloArray,
    contextoNegocioSerie: contextoNegocioSerie,
    contextoNegocio: contextoNegocioSerie[0] || {},
    periodo: datosEntrada.periodo,
    chatInput: datosEntrada.chatInput,
    condiciones_especiales: datosEntrada.condiciones_especiales,
    adr_referencia: datosEntrada.adr_referencia
  }
}];
